function normalize(name: string): string {
	return name.toLowerCase().trim().replace(/[®™]/g, '').replace(/\s+/g, ' ');
}

/** Looks up a known brand by subscription name, trying exact and loose matches. */
export function findBrandIcon(name: string): BrandIcon | undefined {
	const key = normalize(name);

	const slug = aliases[key];
	if (slug) return icons[slug];

	if (colorOnly[key]) return colorOnly[key];

	// loose match: "Netflix Premium" -> "netflix", "Adobe Creative Cloud" -> "adobe"
	for (const [alias, slugForAlias] of Object.entries(aliases)) {
		if (key.includes(alias)) return icons[slugForAlias];
	}
	for (const [alias, brand] of Object.entries(colorOnly)) {
		if (key.includes(alias)) return brand;
	}

	return undefined;
}
